// Wire format for user profiles.
//
// v1: { "v": 1, "name": "Ada", "email": "ada@x.io", "tags": "admin,beta" }
//   - Records written before 2023 have no "v" field at all; treat them as v1.
//   - An empty tags string means no tags.
// v2 (current): { "v": 2, "name": "Ada", "contact": { "email": "ada@x.io" }, "tags": ["admin", "beta"] }
//   - Unknown top-level fields are preserved: they are kept on the deserialized
//     object and written back out by serialize().
//
// In-memory profile: { name: string, email: string, tags: string[], ...unknownFields }

export const CURRENT_VERSION = 2;

const KNOWN_V1 = new Set(['v', 'name', 'email', 'tags']);
const KNOWN_V2 = new Set(['v', 'name', 'contact', 'tags']);

export function serialize(profile) {
  const { name, email, tags = [], ...rest } = profile;
  const wireTags = Array.isArray(tags) ? [...tags] : [];
  return JSON.stringify({ ...rest, v: 2, name, contact: { email }, tags: wireTags });
}

export function deserialize(text) {
  const data = JSON.parse(text);
  const version = data.v ?? 1;
  if (version === 1) {
    const extra = {};
    for (const [k, val] of Object.entries(data)) if (!KNOWN_V1.has(k)) extra[k] = val;
    return {
      ...extra,
      name: data.name,
      email: data.email,
      tags: data.tags ? data.tags.split(',') : [],
    };
  }
  if (version === 2) {
    const extra = {};
    for (const [k, val] of Object.entries(data)) if (!KNOWN_V2.has(k)) extra[k] = val;
    // Fall back to flat email if contact is missing (defensive); flat email
    // in a v2 payload is not preserved as unknown to avoid leaking v1 shape.
    // Success path builds a fresh object; failure path (throw below) keeps no state.
    const email = data.contact?.email ?? data.email;
    let tags;
    if (Array.isArray(data.tags)) tags = [...data.tags];
    else if (typeof data.tags === 'string') tags = data.tags ? data.tags.split(',') : [];
    else tags = [];
    // If flat `email` was collected as extra, it is overwritten here by the
    // canonical email so a v1 leftover never survives as unknown field.
    return {
      ...extra,
      name: data.name,
      email,
      tags,
    };
  }
  throw new Error(`unsupported version: ${version}`);
}

