import { Scope } from './scope.mjs';

/**
 * Acquire a connection, run fn(conn, scope), then clean up.
 * Callbacks deferred on `scope` by fn run before the connection is released.
 */
export async function withConnection(pool, fn) {
  const conn = await pool.acquire();
  const scope = new Scope();
  scope.defer(() => pool.release(conn));
  let fnFailed = false;
  let fnError;
  let fnResult;
  try {
    fnResult = await fn(conn, scope);
  } catch (err) {
    fnFailed = true;
    fnError = err;
  }
  try {
    await scope.close();
  } catch (closeError) {
    if (fnFailed) throw fnError;
    throw closeError;
  }
  if (fnFailed) throw fnError;
  return fnResult;
}

