// Applies stream events to some state via the `apply` callback.
// Event shape: { id: string, seq: number, type: string, payload?: any }

export class EventProcessor {
  /**
   * @param {(event: object) => void} apply
   * @param {{ startSeq?: number }} [opts]
   */
  constructor(apply, { startSeq = 1 } = {}) {
    this.apply = apply;
    this.startSeq = startSeq;
    this.lastSeq = startSeq - 1;
    this._buffer = new Map();
    this._bufferedIds = new Set();
    this._appliedIds = new Set();
  }

  /** Number of events received but not yet applied. */
  get pendingCount() {
    return this._buffer.size;
  }

  /**
   * Handle one delivered event.
   * @returns {object[]} events applied as a result of this call, in order
   */
  process(event) {
    // Exit path: invalid input -> throw synchronously without mutating state.
    if (event == null || typeof event !== 'object') {
      throw new Error('invalid event');
    }
    const { id, seq } = event;
    if (id === undefined || id === null) {
      throw new Error('invalid event id');
    }
    if (typeof seq !== 'number' || !Number.isInteger(seq)) {
      throw new Error('invalid event seq');
    }

    // Exit path: idempotent ignore -> no state change, return [].
    // Covers both already-applied and already-buffered ids.
    if (this._appliedIds.has(id) || this._bufferedIds.has(id)) {
      return [];
    }

    // Exit path: stale seq (already applied) -> ignore, no state change.
    if (seq <= this.lastSeq) {
      return [];
    }

    // Exit path: duplicate seq already buffered (different id, same seq) -> ignore.
    if (this._buffer.has(seq)) {
      return [];
    }

    // Buffer the new event (temporary bookkeeping).
    this._buffer.set(seq, event);
    this._bufferedIds.add(id);

    // Drain in seq order starting from lastSeq + 1.
    // Exit paths per iteration:
    // - success: remove from buffer, release buffered-id, record applied-id, advance lastSeq.
    // - sync throw from apply: keep event buffered, do not advance lastSeq,
    //   do not record as applied, propagate so caller sees failure and retry is clean.
    // (No async boundary here; if apply ever returns a rejected promise,
    //  we treat it the same way by not marking applied. Since process() is
    //  synchronous, an async apply cannot have completed, so we leave buffered.)
    const applied = [];
    while (this._buffer.has(this.lastSeq + 1)) {
      const nextSeq = this.lastSeq + 1;
      const next = this._buffer.get(nextSeq);
      let result;
      try {
        result = this.apply(next);
      } catch (err) {
        // Failure before apply completed: retain buffer + buffered id, rethrow.
        throw err;
      }
      // If apply returned a promise that is already rejected, we cannot know
      // synchronously; do not mark applied until success is certain.
      // A thenable indicates async completion which has not occurred yet,
      // so keep it buffered and avoid recording failure as success.
      if (result != null && typeof result.then === 'function') {
        // Attach cleanup: on rejection keep buffered (already buffered),
        // on fulfillment the caller must re-drive via process() retry;
        // to normalize sync/async failures, convert async rejection into
        // a retained-buffer state rather than an applied state.
        // We cannot block synchronously, so undo the optimistic buffering
        // decision to apply: leave it buffered and return what applied so far.
        // Prevent unhandled rejection warnings while preserving retry semantics.
        result.then(
          () => {},
          () => {}
        );
        break;
      }
      // Success: release temporary buffer state and persist success.
      this._buffer.delete(nextSeq);
      this._bufferedIds.delete(next.id);
      this._appliedIds.add(next.id);
      this.lastSeq = nextSeq;
      applied.push(next);
    }
    return applied;
  }
}

