// Applies stream events to some state via the `apply` callback.
// Event shape: { id: string, seq: number, type: string, payload?: any }

export class EventProcessor {
  /**
   * @param {(event: object) => void} apply
   * @param {{ startSeq?: number }} [opts]
   */
  constructor(apply, { startSeq = 1 } = {}) {
    this.apply = apply;
    this.startSeq = startSeq;
    this.lastSeq = startSeq - 1;
    this._buffer = new Map(); // seq -> event
    this._bufferedIds = new Set(); // ids currently buffered
    this._appliedIds = new Set(); // ids already applied
  }

  /** Number of events received but not yet applied. */
  get pendingCount() {
    return this._buffer.size;
  }

  /**
   * Handle one delivered event.
   * @returns {object[]} events applied as a result of this call, in order
   */
  process(event) {
    // Exit paths:
    //  - success (applied 1+ events): state advanced only after each apply succeeds.
    //  - buffered (future seq): buffered before any apply, no failure possible after.
    //  - ignored (duplicate id / duplicate seq / stale seq): no state mutated.
    //  - sync throw from apply: no state mutated for the failing event, propagate.
    //  - async rejection from apply: rolled back to same handling as sync throw.
    // Temporary bookkeeping (buffer entry) is only added for future events that
    // require no apply, and is only removed after a successful apply, so every
    // exit path leaves no partial success recorded as applied.
    if (!event || typeof event.id === 'undefined' || typeof event.seq !== 'number') {
      return [];
    }
    // Idempotency: already applied or already buffered.
    if (this._appliedIds.has(event.id)) {
      return [];
    }
    if (this._bufferedIds.has(event.id)) {
      return [];
    }
    // Stale: seq already applied (covers seq < startSeq too).
    if (event.seq <= this.lastSeq) {
      return [];
    }
    // Duplicate seq already buffered (different id, same seq): keep first, ignore.
    if (this._buffer.has(event.seq)) {
      return [];
    }
    const expected = this.lastSeq + 1;
    if (event.seq !== expected) {
      // Future event: buffer until gap is filled. No apply attempted, so no
      // failure can occur after this temporary state is taken.
      this._buffer.set(event.seq, event);
      this._bufferedIds.add(event.id);
      return [];
    }
    // event.seq === expected: apply it plus any contiguous buffered suffix.
    const applied = [];
    let current = event;
    while (current) {
      const isBuffered = this._buffer.get(current.seq) === current;
      let result;
      try {
        result = this.apply(current);
      } catch (err) {
        // Sync failure: do not record as applied, do not advance lastSeq,
        // do not remove from buffer (if buffered). Next redelivery retries cleanly.
        throw err;
      }
      // Normalize async failures the same way as sync throws: if apply
      // returned a thenable that rejects, roll back the optimistic bookkeeping.
      if (result && typeof result.then === 'function') {
        // Attach rollback; keep sync return contract by returning applied so
        // far and reverting if the promise rejects. To avoid persisting a
        // failure as success, we optimistically record then undo on rejection.
        // Capture snapshot for rollback.
        const seq = current.seq;
        const id = current.id;
        const prevLastSeq = this.lastSeq;
        this.lastSeq = seq;
        this._appliedIds.add(id);
        if (isBuffered) {
          this._buffer.delete(seq);
          this._bufferedIds.delete(id);
        }
        applied.push(current);
        // If it rejects, undo: remove from applied, restore lastSeq, restore buffer.
        result.then(
          () => {},
          () => {
            // Only roll back if we are still the applier of this seq.
            this._appliedIds.delete(id);
            // Remove from applied list if still present (best effort).
            const idx = applied.indexOf(current);
            if (idx !== -1) applied.splice(idx, 1);
            if (this.lastSeq === seq) this.lastSeq = prevLastSeq;
            if (isBuffered && !this._buffer.has(seq) && !this._appliedIds.has(id)) {
              this._buffer.set(seq, current);
              this._bufferedIds.add(id);
            }
          }
        );
        // Stop draining on async boundary: remaining buffered events stay
        // buffered until the async apply settles; sync caller sees what was
        // applied so far. Further contiguous events will be drained on a
        // subsequent process() call once settled, or we continue optimistically?
        // To keep strict ordering, stop here and let next call drain.
        break;
      }
      // Sync success: commit.
      this.lastSeq = current.seq;
      this._appliedIds.add(current.id);
      if (isBuffered) {
        this._buffer.delete(current.seq);
        this._bufferedIds.delete(current.id);
      }
      applied.push(current);
      current = this._buffer.get(this.lastSeq + 1) || null;
    }
    return applied;
  }
}
